const fieldMap = {
  agenda: 3028198,
  cita_asistida: 3028076,
  cotizacion: 3028078,
  cierre: 3028200,
  campaign: 2972918,
  adset: 2972920,
  ad: 2972924,
};

const users = $('Get Users').first().json._embedded?.users ?? [];
const userNameById = new Map(users.map((u) => [u.id, u.name]));

const pipelines = $('Get Pipelines').first().json._embedded?.pipelines ?? [];
const statusType = new Map();
for (const p of pipelines) {
  for (const s of p._embedded?.statuses ?? []) {
    let type = 'open';
    if (s.id === 142) type = 'won';
    if (s.id === 143) type = 'lost';
    statusType.set(s.id, type);
  }
}

const lossReasons = $('Get Loss Reasons').first().json._embedded?.loss_reasons ?? [];
const lossReasonById = new Map(lossReasons.map((r) => [r.id, r.name]));

const toIso = (unixSeconds) => (unixSeconds ? new Date(unixSeconds * 1000).toISOString() : null);
function extractCustomField(lead, fieldId) {
  const cf = (lead.custom_fields_values || []).find((f) => f.field_id === fieldId);
  return cf?.values?.[0]?.value ?? null;
}
function extractCustomFieldDate(lead, fieldId) {
  const raw = extractCustomField(lead, fieldId);
  const n = Number(raw);
  return raw != null && Number.isFinite(n) ? toIso(n) : null;
}

const lead = $json;
const type = statusType.get(lead.status_id) ?? 'open';

return {
  json: {
    lead_id: lead.id,
    name: lead.name,
    price: lead.price ?? 0,
    pipeline_id: lead.pipeline_id,
    status_id: lead.status_id,
    responsible_user_id: lead.responsible_user_id,
    responsible_user_name: userNameById.get(lead.responsible_user_id) ?? null,
    created_at: toIso(lead.created_at),
    updated_at: toIso(lead.updated_at),
    closed_at: toIso(lead.closed_at),
    is_won: type === 'won',
    is_lost: type === 'lost',
    loss_reason_id: lead.loss_reason_id ?? null,
    loss_reason_name: lead.loss_reason_id ? (lossReasonById.get(lead.loss_reason_id) ?? null) : null,
    campaign: extractCustomField(lead, fieldMap.campaign),
    adset: extractCustomField(lead, fieldMap.adset),
    ad: extractCustomField(lead, fieldMap.ad),
    fecha_agenda: extractCustomFieldDate(lead, fieldMap.agenda),
    fecha_cita_asistida: extractCustomFieldDate(lead, fieldMap.cita_asistida),
    fecha_cotizacion: extractCustomFieldDate(lead, fieldMap.cotizacion),
    fecha_cierre: extractCustomFieldDate(lead, fieldMap.cierre),
  },
};

const pipelines = $input.first().json._embedded?.pipelines ?? [];
const rows = [];
for (const p of pipelines) {
  for (const s of p._embedded?.statuses ?? []) {
    let type = 'open';
    if (s.id === 142) type = 'won';
    if (s.id === 143) type = 'lost';
    rows.push({
      json: {
        pipeline_id: p.id,
        status_id: s.id,
        pipeline_name: p.name,
        status_name: s.name,
        sort: s.sort ?? null,
        status_type: type,
      },
    });
  }
}
return rows;
